import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testHighScoresAbove50() {
        Assert.assertEquals(listOf(72, 91), highScores(listOf(45, 72, 38, 91), 50))
    }

    @Test
    fun testHighScoresAbove25() {
        Assert.assertEquals(listOf(30), highScores(listOf(10, 20, 30), 25))
    }

    @Test
    fun testAllPass() {
        Assert.assertEquals(listOf(50, 60, 70), highScores(listOf(50, 60, 70), 50))
    }

    @Test
    fun testNonePass() {
        Assert.assertEquals(emptyList<Int>(), highScores(listOf(10, 20, 30), 100))
    }

    @Test
    fun testEmptyList() {
        Assert.assertEquals(emptyList<Int>(), highScores(emptyList(), 50))
    }
}
